const esc = (v) => String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;').replace(/`/g, '&#96;');
const safeUrl = (u) => (typeof u === 'string' && /^https?:\/\//i.test(u.trim())) ? u.trim() : null;
const link = (u, label) => { const s = safeUrl(u); return s ? '<a href="' + esc(s) + '" rel="noopener noreferrer nofollow">' + esc(label) + '</a>' : '<span class="muted">' + (u ? esc(u) : '-') + '</span>'; };
const scrub = (t) => String(t || '').replace(/(pass(?:word|wd)?|secret|token|api[_-]?key)([^\n:=]{0,40}[:=]\s*)(?!\[REDACTED\])[^\s]+/gi, '$1$2[REDACTED]');
const rows = (name) => { try { return $(name).all().map((i) => i.json).filter((r) => r && r.slug !== undefined && r.slug !== null); } catch (e) { return []; } };
const clients = rows('Get Clients');
const attempts = rows('Get Attempts');
const byTime = (a, b) => (String(a.started_at || a.createdAt || '')).localeCompare(String(b.started_at || b.createdAt || '')) || ((a.id || 0) - (b.id || 0));
attempts.sort(byTime);
clients.sort((a, b) => (b.legacy ? 1 : 0) - (a.legacy ? 1 : 0) || (a.id || 0) - (b.id || 0));
const legacy = clients.filter((c) => c.legacy === true);
const fleet = clients.filter((c) => c.legacy !== true);
const ram = clients.reduce((s, c) => s + (Number(c.est_ram_mib) || 0), 0);
let cap = null;
for (const a of attempts) {
  if (a.phase !== 'preflight' || !a.capacity_json) continue;
  let j; try { j = JSON.parse(a.capacity_json); } catch (e) { continue; }
  if (j && typeof j.available_mib === 'number') cap = { j, a };
}
const capSummary = (raw) => { if (!raw) return ''; let j; try { j = JSON.parse(raw); } catch (e) { return ''; } if (!j || typeof j !== 'object') return ''; const p = []; if (typeof j.available_mib === 'number') p.push('available ' + j.available_mib + ' MiB'); if (typeof j.clients_that_fit === 'number') p.push('fits ' + j.clients_that_fit); if (typeof j.load5_per_core === 'number') p.push('load/core ' + j.load5_per_core); if (typeof j.free_disk_mib === 'number') p.push('disk ' + j.free_disk_mib + ' MiB'); return p.join(', '); };
const badgeCls = { live: 'ok', active: 'ok', failed_escalated: 'bad', failed_terminal: 'bad', blocked: 'warn', provisioning: 'warn' };
const badge = (s) => '<span class="badge ' + (badgeCls[s] || 'neutral') + '">' + esc(s || 'unknown') + '</span>';
const attemptTable = (list) => list.length ? '<table class="hist"><thead><tr><th>Time</th><th>Phase</th><th>#</th><th>Exit</th><th>Class</th><th>Capacity</th><th>Note</th></tr></thead><tbody>' + list.map((a) => '<tr><td>' + esc(a.started_at) + '</td><td>' + esc(a.phase) + '</td><td>' + esc(a.attempt_no) + '</td><td>' + esc(a.exit_code) + '</td><td>' + esc(a.classification) + (a.decision ? ' <span class="muted">(' + esc(a.decision) + ')</span>' : '') + '</td><td>' + esc(capSummary(a.capacity_json)) + '</td><td>' + esc(a.note) + (a.output_tail ? '<pre>' + esc(scrub(a.output_tail).slice(-600)) + '</pre>' : '') + '</td></tr>').join('') + '</tbody></table>' : '<p class="muted">No recorded attempts.</p>';
const tile = (label, value, sub) => '<div class="tile"><div class="tl">' + esc(label) + '</div><div class="tv">' + esc(value) + '</div>' + (sub ? '<div class="ts">' + esc(sub) + '</div>' : '') + '</div>';
const known = new Set(clients.map((c) => c.slug));
const orphans = attempts.filter((a) => !known.has(a.slug));
const capTile = cap ? tile('Latest capacity check', cap.j.available_mib + ' MiB free', 'fits ' + cap.j.clients_that_fit + ' more - ' + (cap.a.decision || '?') + ' - ' + (cap.a.started_at || '')) : tile('Latest capacity check', 'none yet', '');
const tr = (c) => { const ro = c.read_only === true || c.legacy === true; const list = attempts.filter((a) => a.slug === c.slug); return '<tr><td>' + esc(c.client_name) + (c.legacy === true ? ' <span class="badge legacy">legacy - read-only</span>' : '') + '<div class="muted">' + esc(c.slug) + (c.business_name ? ' / ' + esc(c.business_name) : '') + '</div></td><td>' + esc(c.subdomain) + '</td><td>' + badge(c.status) + '</td><td>' + link(c.site_url, 'site') + ' &middot; ' + link(c.admin_url, '/admin') + '</td><td class="num">' + esc(c.est_ram_mib) + '</td></tr><tr class="det"><td colspan="5"><details><summary>History (' + list.length + ' attempts)' + (ro ? ' - read-only' : '') + '</summary>' + attemptTable(list) + '</details></td></tr>'; };
const css = ':root{--bg:#f6f7f9;--fg:#1c2330;--card:#fff;--mut:#667085;--bd:#e2e5ea;--ok:#0a7d4b;--bad:#b42318;--warn:#a15c07}@media(prefers-color-scheme:dark){:root{--bg:#0f1420;--fg:#e6e9ef;--card:#182031;--mut:#93a0b5;--bd:#2a3550;--ok:#4cd39a;--bad:#ff8a80;--warn:#f5b85a}}*{box-sizing:border-box}body{margin:0;padding:16px;background:var(--bg);color:var(--fg);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}main{max-width:1100px;margin:0 auto}h1{font-size:1.4rem;margin:0 0 4px}h2{font-size:1.05rem;margin:28px 0 8px}a{color:inherit}.muted{color:var(--mut);font-size:.85em}.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin-top:16px}.tile{background:var(--card);border:1px solid var(--bd);border-radius:10px;padding:12px 14px}.tl{color:var(--mut);font-size:.8rem}.tv{font-size:1.4rem;font-weight:600}.ts{color:var(--mut);font-size:.8rem}.wrap{overflow-x:auto;background:var(--card);border:1px solid var(--bd);border-radius:10px}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:8px 12px;border-bottom:1px solid var(--bd);vertical-align:top}th{font-size:.75rem;color:var(--mut);text-transform:uppercase}.num{text-align:right}.badge{display:inline-block;padding:1px 8px;border-radius:999px;font-size:.75rem;border:1px solid var(--bd);white-space:nowrap}.badge.ok{color:var(--ok);border-color:var(--ok)}.badge.bad{color:var(--bad);border-color:var(--bad)}.badge.warn{color:var(--warn);border-color:var(--warn)}.badge.legacy{color:var(--mut)}tr.det td{background:transparent}summary{cursor:pointer;color:var(--mut)}.hist{font-size:.85em;margin-top:8px}pre{white-space:pre-wrap;word-break:break-word;margin:4px 0 0;padding:6px;border:1px solid var(--bd);border-radius:6px;font-size:.8em;max-height:12em;overflow:auto}';
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Qubix fleet</title><style>' + css + '</style></head><body><main><h1>Qubix fleet</h1><div class="muted">Read-only. Generated ' + esc(new Date().toISOString()) + '</div><div class="tiles">' + tile('Fleet clients', fleet.length, '') + tile('Legacy sites', legacy.length, 'read-only') + tile('Est. RAM footprint', ram + ' MiB', 'sum of est_ram_mib') + capTile + '</div><h2>Clients</h2><div class="wrap"><table><thead><tr><th>Client</th><th>Subdomain</th><th>Status</th><th>Links</th><th class="num">Est. MiB</th></tr></thead><tbody>' + clients.map(tr).join('') + '</tbody></table></div>' + (orphans.length ? '<h2>Requests without a client record</h2><div class="wrap"><details open><summary>' + orphans.length + ' rows (rejected / blocked requests)</summary><table class="hist"><thead><tr><th>Slug</th><th>Time</th><th>Phase</th><th>Class</th><th>Capacity</th><th>Note</th></tr></thead><tbody>' + orphans.map((a) => '<tr><td>' + esc(a.slug) + '</td><td>' + esc(a.started_at) + '</td><td>' + esc(a.phase) + '</td><td>' + esc(a.classification) + ' <span class="muted">(' + esc(a.decision) + ')</span></td><td>' + esc(capSummary(a.capacity_json)) + '</td><td>' + esc(a.note) + '</td></tr>').join('') + '</tbody></table></details></div>' : '') + '</main></body></html>';
return [{ json: { html } }];
